From b3d86e3e2d33d2ba1ec7e0064531010553ef056a Mon Sep 17 00:00:00 2001
From: David Anderson <davea42@linuxmail.org>
Date: Sat, 15 Jun 2024 11:00:44 -0700
Subject: [PATCH] Remove debug printf (was #if 0 ... #endif) Fixed DW202406-001
  ossfuzz 69639 and DW202406-002 ossfuzz 69641 The bug in reading DWARF5
 .debug_loclists was in the code for a couple weeks. 	modified:  
 src/lib/libdwarf/dwarf_loclists.c

---
 src/lib/libdwarf/dwarf_loclists.c | 118 +++++++++++++-----------------
 1 file changed, 49 insertions(+), 69 deletions(-)

diff --git a/src/lib/libdwarf/dwarf_loclists.c b/src/lib/libdwarf/dwarf_loclists.c
index 5ceaaf5..0e19094 100644
--- a/src/lib/libdwarf/dwarf_loclists.c
+++ b/src/lib/libdwarf/dwarf_loclists.c
@@ -73,7 +73,7 @@ dump_bytes(const char *msg,Dwarf_Small * start, long len)
             printf("[0x%04lx] ",(unsigned long)full);
         }
         printf("%02x", *cur);
-        ++ct; 
+        ++ct;
         if ( ct % 4 == 0) {
             printf(" ");
         }
@@ -86,9 +86,20 @@ dump_bytes(const char *msg,Dwarf_Small * start, long len)
 }
 #endif /*0*/

+static void
+free_loclists_context(Dwarf_Loclists_Context cx)
+{
+    if (cx) {
+        free(cx->lc_offset_value_array);
+        cx->lc_offset_value_array = 0;
+        free(cx);
+    }
+}
+
 /*  Used in case of error reading the
     loclists headers (not referring to Dwarf_Loc_Head_c
-    here), to clean up. */
+    here), to clean up. The chain is of
+    Dwarf_Loclists_Context items */
 static void
 free_loclists_chain(Dwarf_Debug dbg, Dwarf_Chain head)
 {
@@ -101,7 +112,9 @@ free_loclists_chain(Dwarf_Debug dbg, Dwarf_Chain head)
     for ( ;cur; cur = next) {
         next = cur->ch_next;
         if (cur->ch_item) {
-            free(cur->ch_item);
+            Dwarf_Loclists_Context cx =
+                (Dwarf_Loclists_Context)cur->ch_item;
+            free_loclists_context(cx);
             cur->ch_item = 0;
             dwarf_dealloc(dbg,cur,DW_DLA_CHAIN);
         }
@@ -340,14 +353,6 @@ read_single_lle_entry(Dwarf_Debug dbg,
     return DW_DLV_OK;
 }

-static void
-free_loclists_context(Dwarf_Loclists_Context cx)
-{
-    free(cx->lc_offset_value_array);
-    cx->lc_offset_value_array = 0;
-    free(cx);
-}
-
