+            " The debug_loclists offset table entry "
+            "count exceeds the "
             "section length, Corrupt dwarf");
         return DW_DLV_ERROR;
     }
-    buildhere->lc_offset_value_array = (Dwarf_Unsigned *)
-        calloc(offset_entry_count, sizeof(Dwarf_Unsigned));
-    if (!buildhere->lc_offset_value_array) {
