+            buildhere->lc_offset_value_array[tabentrynum] = entry;
+            lists_len += SIZEOFT32;
         }
-#if 0
-        READ_UNALIGNED_CK(dbg,entry,Dwarf_Unsigned,data,
-          SIZEOFT32,error,end_data);
-#endif
-        buildhere->lc_offset_value_array[tabentrynum] = entry;
-        lists_len += SIZEOFT32;
-    }
+    } /* else no offset table */

