         if (theform == DW_FORM_sec_offset) {
             /*  DW_FORM_sec_offset is not formudata , often
                 seen in in DW5 DW_AT_location etc */
@@ -1339,8 +1326,8 @@ _dwarf_loclists_fill_in_lle_head(Dwarf_Debug dbg,
