-(unsigned long)lle_global_offset,__LINE__,__FILE__);
-#endif
     } else {
         lle_global_offset = attr_val;
     }
@@ -1451,7 +1432,6 @@ _dwarf_free_loclists_limited_head_content(Dwarf_Loc_Head_c head)
